5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	
14	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	};
20	
21	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
22	const COMPONENT_BASE_PREMIUM = 25;
23	const BLOCK_SIZE = 3;
24	const BLOCK_BASE_PREMIUM = 60;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	const LOYALTY_YEARS = 2;
27	const LOYALTY_DISCOUNT_RATE = 0.2;
28	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
29	const CURSE_SURCHARGE_RATE = 0.5;
30	const HIGH_ENCHANTMENT_LEVEL = 5;
31	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
32	
33	function isComponent(item: Item): boolean {
34	  return COMPONENT_TYPES.has(item.type);
35	}
36	
37	function mainItemBasePremium(item: Item): number {
38	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
39	}
40	
41	function sum(amounts: number[]): number {
42	  return amounts.reduce((total, amount) => total + amount, 0);
43	}
44	
45	function alikeComponentsBasePremium(alikeComponents: Item[]): number {
46	  return alikeComponents.length === BLOCK_SIZE
47	    ? BLOCK_BASE_PREMIUM
48	    : alikeComponents.length * COMPONENT_BASE_PREMIUM;
49	}
50	
51	// "Alike" components are components of exactly the same type, not merely of
52	// the same family; only alike components can form a building block.
53	function alikeKey(component: Item): string {
54	  return component.type;
55	}
56	
57	function groupAlikeComponents(components: Item[]): Item[][] {
58	  const groups = new Map<string, Item[]>();
59	  for (const component of components) {
60	    const key = alikeKey(component);
61	    const group = groups.get(key) ?? [];
62	    group.push(component);
63	    groups.set(key, group);
64	  }
65	  return [...groups.values()];
66	}
67	
68	function componentsBasePremium(components: Item[]): number {
69	  return sum(groupAlikeComponents(components).map(alikeComponentsBasePremium));
70	}
71	
72	export function policyBasePremium(items: Item[]): number {
73	  const components = items.filter(isComponent);
74	  const mainItems = items.filter((item) => !isComponent(item));
75	  return (
76	    sum(mainItems.map(mainItemBasePremium)) + componentsBasePremium(components)
77	  );
78	}
79	
80	function itemBasePremium(item: Item): number {
81	  return isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemBasePremium(item);
82	}
83	
84	function isCursed(item: Item): boolean {
85	  return item.cursed === true;
86	}
87	
88	function isHighlyEnchanted(item: Item): boolean {
89	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
90	}
91	
92	// An item bears every risk factor it qualifies for; a cursed, highly enchanted
93	// item therefore carries both surcharges.
94	function itemRiskSurchargeRate(item: Item): number {
95	  const curse = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
96	  const highEnchantment = isHighlyEnchanted(item)
97	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
98	    : 0;
99	  return curse + highEnchantment;
100	}
101	
102	function itemRiskSurcharge(item: Item): number {
103	  return itemBasePremium(item) * itemRiskSurchargeRate(item);
104	}
105	
106	// Item-specific modifiers apply to the base premium of the affected item.
107	function itemRiskSurcharges(items: Item[]): number {
108	  return sum(items.map(itemRiskSurcharge));
109	}
110	
111	// The customer's standing with MHPCO, as far as the premium is concerned.
112	interface CustomerStanding {
113	  customer: Customer;
114	  previousContracts: number;
115	}
116	
117	// Every item in a quote is treated as a first insurance, regardless of the
118	// customer's history, so this surcharge does not depend on the customer.
119	function firstInsuranceSurcharge(basePremium: number): number {
120	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
121	}
122	
123	function isLongStanding({ customer }: CustomerStanding): boolean {
124	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
125	}
126	
127	function loyaltyDiscount(
128	  standing: CustomerStanding,
129	  basePremium: number,
130	): number {
131	  return isLongStanding(standing) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
132	}
133	
134	// Every contract after the customer's first is a follow-up contract.
135	function isFollowUpContract({ previousContracts }: CustomerStanding): boolean {
136	  return previousContracts > 0;
137	}
138	
139	function followUpContractDiscount(
140	  standing: CustomerStanding,
141	  basePremium: number,
142	): number {
143	  return isFollowUpContract(standing)
144	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
145	    : 0;
146	}
147	
148	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) all
149	// apply to the policy base premium. Returns the net adjustment: surcharges
150	// positive, discounts negative. Each modifier is applied to the base premium
151	// separately rather than as a summed rate, so that intermediate amounts match
152	// the per-modifier figures in the MHPCO's own worked examples.
153	function policyWideModifiers(
154	  standing: CustomerStanding,
155	  basePremium: number,
156	): number {
157	  return (
158	    firstInsuranceSurcharge(basePremium) -
159	    loyaltyDiscount(standing, basePremium) -
160	    followUpContractDiscount(standing, basePremium)
161	  );
162	}
163	
164	export function quote(
165	  customer: Customer,
166	  items: Item[],
167	  previousContracts = 0,
168	): number {
169	  const basePremium = policyBasePremium(items);
170	  return (
171	    basePremium +
172	    itemRiskSurcharges(items) +
173	    policyWideModifiers({ customer, previousContracts }, basePremium) +
174	    PROCESSING_FEE
175	  );
176	}
